@@ -27,3 +28,28 @@ test("waste is recorded against a batch", () => {
   assert.equal(m.type, "waste");
   assert.equal(store.data.batches.find((b) => b.id === 6).qty, 12);
 });
+
+test("cooking uses the batch that expires first (FEFO)", () => {
+  const store = fresh();
+  // Bechamel (recipe 2) needs milk (item 2): lot HD-1022 expires before the
+  // newer lot HD-1026 and must be used first.
+  const used = cook(store, 2, 5, { at });
+  const milk = used.find((u) => u.itemId === 2);
+  assert.deepEqual(milk.batches, [{ batchId: 4, qty: 1 }]);
+  assert.equal(store.data.batches.find((b) => b.id === 4).qty, 1);
+  assert.equal(store.data.batches.find((b) => b.id === 3).qty, 8);
+});
+
+test("consume orders by expiry, then received day, then id; no expiry last", () => {
+  const store = fresh();
+  const mk = (id, receivedOn, expires) =>
+    store.data.batches.push({ id, itemId: 99, lot: `T-${id}`, qty: 1, receivedOn, expires, location: "fridge" });
+  store.data.items.push({ ...store.data.items.find((i) => i.id === 2), id: 99, name: "test item" });
+  mk(100, "2026-10-01", null);
+  mk(101, "2026-10-20", "2026-11-05");
+  mk(102, "2026-10-10", "2026-11-05");
+  mk(103, "2026-10-25", "2026-11-01");
+  mk(104, "2026-10-10", "2026-11-05");
+  const used = consume(store, 99, 5, { at });
+  assert.deepEqual(used.map((u) => u.batchId), [103, 102, 104, 101, 100]);
+});
